package practice;

import java.math.BigDecimal;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;

/** The new pricing code's view of the legacy FX client: one future per lookup. */
public final class Rates {

    /** The legacy client's callback. Exactly one method is called per lookup that was accepted. */
    public interface RateListener {
        void onRate(String pair, BigDecimal rate);

        void onFailure(String pair, String reason);
    }

    /** The legacy FX client. Don't change it. */
    public interface RateClient {
        /**
         * Checks {@code pair} on the calling thread and throws IllegalArgumentException if it is not
         * of the form "EUR/USD"; otherwise returns at once and answers later, on a thread of its own.
         */
        void lookup(String pair, RateListener listener);
    }

    /** What a future fails with when the client reports a failure. */
    public static final class RateUnavailableException extends RuntimeException {
        public RateUnavailableException(String message) {
            super(message);
        }
    }

    private final RateClient client;

    public Rates(RateClient client) {
        this.client = Objects.requireNonNull(client);
    }

    /** The rate for {@code pair}, as a future that the client's answer completes. */
    public CompletableFuture<BigDecimal> rate(String pair) {
        CompletableFuture<BigDecimal> result = new CompletableFuture<>();
        try {
            client.lookup(pair, new RateListener() {
                @Override
                public void onRate(String p, BigDecimal rate) {
                    result.complete(rate);
                }

                @Override
                public void onFailure(String p, String reason) {
                    result.completeExceptionally(new RateUnavailableException(p + ": " + reason));
                }
            });
        } catch (RuntimeException e) {
            result.completeExceptionally(e);
        }
        return result;
    }
}

package practice;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Map<String, Rates.RateListener> waiting = new ConcurrentHashMap<>();
            Rates rates = new Rates((pair, listener) -> {
                if (!pair.matches("[A-Z]{3}/[A-Z]{3}")) throw new IllegalArgumentException("not a currency pair: " + pair);
                waiting.put(pair, listener);
            });
            CompletableFuture<BigDecimal> eurUsd = rates.rate("EUR/USD");
            CompletableFuture<BigDecimal> nokDkk = rates.rate("NOK/DKK");
            CompletableFuture<BigDecimal> bad = rates.rate("eur-usd");
            System.out.println("EUR/USD done before the client answers: " + eurUsd.isDone());
            Thread client = new Thread(() -> {
                waiting.get("EUR/USD").onRate("EUR/USD", new BigDecimal("1.0763"));
                waiting.get("NOK/DKK").onFailure("NOK/DKK", "feed stale");
            }, "fx-io");
            client.start();
            client.join();
            System.out.println("EUR/USD: " + eurUsd.orTimeout(2, TimeUnit.SECONDS).join());
            System.out.println("NOK/DKK: " + nokDkk.orTimeout(2, TimeUnit.SECONDS).handle((r, e) -> r != null ? r.toString() : "failed: " + e.getMessage()).join());
            System.out.println("eur-usd: " + bad.handle((r, e) -> r != null ? r.toString() : "failed: " + e.getMessage()).join());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

